<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT b.*,u.full_name FROM bills b JOIN users u ON u.id=b.cashier_id WHERE b.id=?');$st->execute([$id]);$b=$st->fetch();$it=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$it->execute([$id]);$items=$it->fetchAll();if(!$b)exit('Bill haipo');?><!doctype html><html lang="sw"><head><meta charset="utf-8"><title>Bill <?=e($b['bill_no'])?></title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="receipt"><div class="text-center"><h2>RESTAURANT</h2><h3>BILL / INVOICE</h3><p>Bill No: <b><?=e($b['bill_no'])?></b><br><?=e($b['created_at'])?><br>Mteja: <?=e($b['customer_name']?:'Walk-in')?></p></div><table><tr><th>Aina/Bidhaa</th><th>Idadi</th><th>Bei</th><th>Jumla</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['quantity'])?></td><td><?=number_format($i['unit_price'],2)?></td><td><?=number_format($i['line_total'],2)?></td></tr><?php endforeach;?></table><h2 class="text-center">TOTAL: TSh <?=number_format($b['total'],2)?></h2><p>Cashier: <?=e($b['full_name'])?> | Status: <?=e($b['status'])?></p><div class="actions no-print"><button onclick="window.print()">Print Bill</button><a class="btn gray" href="../bills/index.php">Back</a></div></div></body></html>
